contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take as input: the pool address (as msg.sender for minting), and the member to receive synth,
    // and an amount that the pool will claim to have added as LP units by transferring LP tokens into C.
    // Because the checker deploys a fresh C, we must drive state via external observable calls only.
    // We'll simulate a Pool by using the test contract itself as the caller for mintSynth (but the contract
    // invoking must be reported as msg.sender to C). To achieve that, we require the caller of run to be the
    // deployer externally; however the checker will call run directly. Instead we rely that c.mintSynth is
    // gated by onlyPool which queries POOLFACTORY via C._DAO().POOLFACTORY().isCuratedPool(msg.sender).
    // Because we cannot change the DAO/POOLFACTORY from here, the safe way is to call c.mintSynth via
    // a low-level call from this contract so that msg.sender seen by C is this contract. That still won't
    // satisfy onlyPool unless the factory considers this contract curated. To avoid relying on that external
    // truth, we instead call mintSynth via try/catch to capture whether it reverts; the property asserts
    // that if it succeeds then totalSupply increased by exactly 'amount' and mapSynth_LPDebt increased by amount.

    function run(address pool, address member, uint amount) public payable {
        require(member != address(0), "member0");
        // Read before-values
        uint beforeTotal = c.totalSupply();
        uint beforeDebt = c.getmapAddress_LPDebt(pool);
        uint beforeBalanceMember = c.balanceOf(member);

        bool reverted;
        // Attempt the call as this contract (msg.sender = this contract). We must make it a top-level statement.
        try c.mintSynth(member, amount) returns (uint syntheticAmount) {
            reverted = false;
            // after-values when succeeded
            uint afterTotal = c.totalSupply();
            uint afterDebt = c.getmapAddress_LPDebt(pool);
            uint afterBalanceMember = c.balanceOf(member);

            // The general invariant we assert below will relate these values.
            // To make them available to the final assert we store them in local variables via no-op.
            beforeTotal = beforeTotal;
            beforeDebt = beforeDebt;
            beforeBalanceMember = beforeBalanceMember;
            afterTotal = afterTotal;
            afterDebt = afterDebt;
            afterBalanceMember = afterBalanceMember;

        } catch {
            reverted = true;
        }

        // Now the single general assertion:
        // If the call reverted, then nothing is required about balances. If it succeeded (reverted==false), then:
        //  - totalSupply increased by exactly 'amount'
        //  - member's balance increased by exactly 'amount'
        //  - mapSynth_LPDebt for the pool increased by exactly 'amount'
        // We can't reference after-values defined inside the try block from here, so re-query current state.
        uint finalTotal = c.totalSupply();
        uint finalDebt = c.getmapAddress_LPDebt(pool);
        uint finalBalanceMember = c.balanceOf(member);

        assert(reverted || (finalTotal >= beforeTotal && finalBalanceMember >= beforeBalanceMember && finalDebt >= beforeDebt &&
               finalTotal - beforeTotal == amount && finalBalanceMember - beforeBalanceMember == amount && finalDebt - beforeDebt == amount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Run attempts to call mintSynth with member and amount as parameters.
    // It captures whether the call reverted. If it succeeded, it asserts that
    // totalSupply, member balance, and mapSynth_LPDebt for msg.sender (the caller) increased by exactly the minted amount.
    function run(address member, uint amount) public payable {
        require(member != address(0), "member0");

        // Observe before-values
        uint beforeTotal = c.totalSupply();
        uint beforeMember = c.balanceOf(member);
        uint beforeDebt = c.getmapAddress_LPDebt(address(this));

        bool reverted = false;
        uint returnedAmount = 0;
        // Top-level state-changing call on c
        try c.mintSynth(member, amount) returns (uint syntheticAmount) {
            reverted = false;
            returnedAmount = syntheticAmount;
        } catch {
            reverted = true;
        }

        // Observe after-values
        uint afterTotal = c.totalSupply();
        uint afterMember = c.balanceOf(member);
        uint afterDebt = c.getmapAddress_LPDebt(address(this));

        // If call reverted then none of the three observed values should have increased by the requested amount.
        // If call succeeded then each increased exactly by returnedAmount and returnedAmount equals 'amount' per spec of mintSynth.
        // (We allow returnedAmount to be 0 in some implementations, but then increases must be 0.)
        assert(
            reverted
            ? (afterTotal == beforeTotal && afterMember == beforeMember && afterDebt == beforeDebt)
            : (afterTotal == beforeTotal + returnedAmount && afterMember == beforeMember + returnedAmount && afterDebt == beforeDebt + returnedAmount)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call burnSynth as if msg.sender is a pool (this contract). We observe before/after for totalSupply and mapSynth_LPDebt.
    // We assert a general relation: if burnSynth succeeds then the pool's recorded debt decreases by at least the amount burned (the synth balance of C before call), and totalSupply does not increase.
    function run() public payable {
        // Observe before-values
        uint beforeTotal = c.totalSupply();
        uint beforeDebt = c.getmapAddress_LPDebt(address(this));
        uint beforeSynthBal = c.balanceOf(address(this));

        bool reverted = false;
        try c.burnSynth() returns (bool ok) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterTotal = c.totalSupply();
        uint afterDebt = c.getmapAddress_LPDebt(address(this));
        uint afterSynthBal = c.balanceOf(address(this));

        // General rule:
        // - If the call reverted, neither totalSupply nor the pool's debt should have increased.
        // - If the call succeeded, then the pool's recorded debt decreased by at least the amount of synth that was burned (which equals beforeSynthBal), and totalSupply did not increase.
        assert(
            reverted
            ? (afterTotal <= beforeTotal && afterDebt <= beforeDebt)
            : (afterTotal <= beforeTotal && afterDebt + beforeSynthBal <= beforeDebt && afterSynthBal <= beforeSynthBal)
        );
    }

    receive() external payable {}
}

