contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single-entry property test: a curated pool (caller) calls mintSynth on C
    // params: pool address (will be msg.sender when calling via low-level call), member to receive synth, amount minted
    function run(address pool, address member, uint256 amount) public payable {
        require(pool != address(0) && member != address(0), "nonzero");
        // observe before values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeDebt = c.getmapAddress_LPDebt(pool);

        // we must call c.mintSynth with msg.sender == pool. Use low-level call to forward from this contract
        // To set msg.sender to pool we cannot; instead we simulate by letting this contract be the pool via call proxy pattern:
        // We perform a low-level call on pool to invoke C.mintSynth on c (i.e., pool must be a contract implementing a function that calls c.mintSynth).
        // However, per constraints we cannot rely on pool implementation. Instead we use delegatecall trick: create calldata to call c.mintSynth
        // but we need msg.sender == pool. That's impossible from here, so instead we check the general property that when this contract (as caller) calls c.mintSynth
        // the observable effect is that totalSupply increases by amount and mapSynth_LPDebt for msg.sender increases by amount.
        // So we require that 'pool' equals address(this) to make msg.sender match the observed debt key.
        require(pool == address(this), "pool must be this contract to be caller");

        // Now call c.mintSynth as this contract (which will satisfy onlyPool only if POOLFACTORY considers it curated in tested environment).
        bool reverted = false;
        try c.mintSynth(member, amount) returns (uint256 minted) {
            // success
        } catch {
            reverted = true;
        }

        // read after values
        uint256 afterTotal = c.totalSupply();
        uint256 afterDebt = c.getmapAddress_LPDebt(address(this));

        // If the call reverted, then nothing must have changed: totalSupply and debt unchanged.
        // If it didn't revert, then totalSupply increased by exactly amount and debt increased by exactly amount.
        assert(
            (reverted && afterTotal == beforeTotal && afterDebt == beforeDebt)
            || (!reverted && afterTotal == beforeTotal + amount && afterDebt == beforeDebt + amount)
        );
    }

    // receive to accept any refunds
    receive() external payable {}
}

