contract InvMutTest {
    C c;
    address pool;
    constructor(C _c) { c = _c; pool = msg.sender; }

    // We take as parameters: the pool address (must be a curated pool as per DAO),
    // an external member to receive minted synth, and an amount to mint.
    function run(address curatedPool, address member, uint256 amount) public payable {
        require(curatedPool != address(0) && member != address(0));
        // Pre-state observations
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeDebt = c.getmapAddress_LPDebt(curatedPool);

        // We must call mintSynth as if called by the pool; since the checker deploys c and
        // then calls run with msg.sender = InvMutTest, we simulate call-from-pool by
        // invoking c.mintSynth through a low-level call with curatedPool as msg.sender
        // is impossible; instead the spec allows only calling c as this contract. However
        // C's mintSynth has onlyPool modifier which requires msg.sender to be a curated pool.
        // To reach the body we attempt the call and record whether it reverted.
        bool reverted;
        bytes memory ret;
        try c.mintSynth(member, amount) returns (uint256 retAmount) {
            reverted = false;
            // reflect returned value into ret for later check via abi.encode
            ret = abi.encode(retAmount);
        } catch {
            reverted = true;
            ret = "";
        }

        // Post-state observations
        uint256 afterTotal = c.totalSupply();
        uint256 afterDebt = c.getmapAddress_LPDebt(curatedPool);

        // If call reverted, then neither totalSupply nor mapSynth_LPDebt should have increased.
        // If call succeeded, returned amount equals increase in totalSupply and mapSynth_LPDebt increased by amount.
        // We assert this combined property.
        if (reverted) {
            assert(afterTotal == beforeTotal && afterDebt == beforeDebt);
        } else {
            // decode returned amount
            uint256 returned = abi.decode(ret, (uint256));
            assert(afterTotal == beforeTotal + returned && afterDebt == beforeDebt + returned);
        }
    }

    receive() external payable { }
}

