contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Simulate a curated pool calling mintSynth(poolMember, amount)
    // Parameters:
    // - pool: address of the pool (msg.sender for C.mintSynth must be a curated pool; we cannot make external contracts here,
    //   but the checker deploys C and will allow any address to be passed — mintSynth enforces onlyPool which calls
    //   iPOOLFACTORY(_DAO().POOLFACTORY()).isCuratedPool(msg.sender). Since we cannot satisfy that externally in general,
    //   this test treats the call as potentially reverting and asserts the general relationship when call succeeds.
    function run(address pool, address member, uint amount) public payable {
        require(amount <= type(uint256).max, true);

        // read before-values
        uint beforeTotal = c.totalSupply();
        uint beforeDebt = c.getmapAddress_LPDebt(pool);
        uint beforeLPBal = c.getmapAddress_LPBalance(pool);

        // attempt the state-changing call and record whether it reverted
        bool reverted;
        try c.mintSynth{value:0}(member, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint afterTotal = c.totalSupply();
        uint afterDebt = c.getmapAddress_LPDebt(pool);
        uint afterLPBal = c.getmapAddress_LPBalance(pool);

        // If the call reverted then nothing observable should have changed in C's public storage
        // (mintSynth is the only state-changing call we made). If it succeeded, then
        // afterTotal == beforeTotal + amount, afterDebt == beforeDebt + amount, and afterLPBal >= beforeLPBal.
        assert(reverted
            ? (afterTotal == beforeTotal && afterDebt == beforeDebt && afterLPBal == beforeLPBal)
            : (afterTotal == beforeTotal + amount && afterDebt == beforeDebt + amount && afterLPBal >= beforeLPBal)
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params:
    // poolAddr: intended pool (will be seen by C as msg.sender when the call is proxied from this contract)
    // member: recipient of minted synth
    // amount: amount to mint
    function run(address poolAddr, address member, uint256 amount) public payable {
        // read before-values for the specific pool address
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeDebt = c.getmapAddress_LPDebt(poolAddr);
        uint256 beforeLPBal = c.getmapAddress_LPBalance(poolAddr);

        // We want to attempt mintSynth as if called by poolAddr. The checker will set up C such that
        // onlyPool may allow or disallow this; here we perform the call and catch revert.
        bool reverted;
        // Call must be a top-level statement. We call on c; msg.sender will be this contract.
        try c.mintSynth(member, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint256 afterTotal = c.totalSupply();
        uint256 afterDebt = c.getmapAddress_LPDebt(poolAddr);
        uint256 afterLPBal = c.getmapAddress_LPBalance(poolAddr);

        // If call reverted, no observable change. If succeeded, totalSupply increased by amount,
        // debt increased by amount, and LP balance did not decrease (i.e., afterLPBal >= beforeLPBal).
        assert(
