                afterTotal == beforeTotal
                && afterPoolDebt == beforePoolDebt
                && afterPoolLPBal == beforePoolLPBal
                && afterThisBal == beforeThisBal
              )
            : (
                // Otherwise: totalSupply and this balance decrease by same amount,
                // pool debt decreases by that same amount, and pool LP balance does not increase.
                afterTotal <= beforeTotal
                && afterThisBal <= beforeThisBal
                && afterPoolDebt <= beforePoolDebt
                && afterPoolLPBal <= beforePoolLPBal
                && (beforeTotal - afterTotal) == (beforeThisBal - afterThisBal)
                && (beforePoolDebt - afterPoolDebt) == (beforeThisBal - afterThisBal)
              )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry point
    // pool - address that will be treated as msg.sender by the pool-call simulation
    // member - recipient of minted synth
    // addedLP - amount of LP tokens that the pool has transferred to C prior to minting (simulate by making c hold more of pool token)
    // amount - requested synthetic amount to mint
    function run(address pool, address member, uint256 addedLP, uint256 amount) public payable {
        require(pool != address(0) && member != address(0), "bad");

        // Preconditions: ensure this contract holds tokens representing LP for `pool` contract
        // We cannot mint arbitrary ERC20 here; instead we rely on visibility of balance via iBEP20 interface through C's public functions.
        // The test will call c.mintSynth as if msg.sender == pool by using low-level call with pool as sender is impossible here,
        // but contract C's onlyPool modifier checks iPOOLFACTORY(...).isCuratedPool(msg.sender) == true and msg.sender == DEPLOYER for onlyDAO.
        // We cannot change msg.sender of external call; however the property can still be expressed by invoking c.mintSynth via .mintSynth where msg.sender is this test contract.
        // To respect constraints, we will assert a relation between observable state changes when c.mintSynth is invoked: minted balance increases by `amount` and mapSynth_LPDebt for `pool` increases by `amount` when the call succeeds.

        // Read before-values
        uint256 beforeMemberBal = c.balanceOf(member);
        uint256 beforeDebt = c.getmapAddress_LPDebt(pool);
        uint256 beforeLPbalance = c.getmapAddress_LPBalance(pool);

        // Try calling mintSynth; catch revert
        bool reverted = false;
        try c.mintSynth(member, amount) returns (uint256 minted) {
            // minted returned
        } catch {
            reverted = true;
        }

        // Read after-values
        uint256 afterMemberBal = c.balanceOf(member);
        uint256 afterDebt = c.getmapAddress_LPDebt(pool);
        uint256 afterLPbalance = c.getmapAddress_LPBalance(pool);

        // General rule asserted:
        // If the call did not revert, then the member's balance increased by exactly `amount` and the pool debt increased by exactly `amount`.
        // If the call reverted, we make no claim about balances. This is a general correctness property of mintSynth's accounting.
        assert(reverted || (afterMemberBal == beforeMemberBal + amount && afterDebt == beforeDebt + amount));
    }

    receive() external payable {}
}

