contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // pool: the calling pool (must be a curated pool in DAO for call to succeed)
    // member: recipient of minted synth
    // amount: requested synthetic amount to mint
    function run(address pool, address member, uint256 amount) public payable {
        require(pool != address(0) && member != address(0), "bad");

        // observe before-values via public interface
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeMember = c.balanceOf(member);

        // call mintSynth as if from the pool: since the checker deploys c and then calls run()
        // msg.sender for calls on c will be this contract. To simulate a call from pool,
        // we invoke c.mintSynth by making the pool perform the call externally is not possible here,
        // but the specification of the harness says msg.sender for calls on c is InvMutTest, and
        // pools are expected to call c.mintSynth; instead we directly call c.mintSynth and record revert.
        bool reverted = false;
        uint256 minted = 0;
        try c.mintSynth(member, amount) returns (uint256 out) {
            minted = out;
        } catch {
            reverted = true;
        }

        // read after-values
        uint256 afterTotal = c.totalSupply();
        uint256 afterMember = c.balanceOf(member);

        // General rule: if the call did not revert then totalSupply increased by exactly minted
        // and member balance increased by exactly minted. If it reverted, no claim is made.
        assert(reverted || (afterTotal == beforeTotal + minted && afterMember == beforeMember + minted));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // member: recipient of minted synth
    // amount: requested synthetic amount to mint
    function run(address member, uint256 amount) public payable {
        require(member != address(0), "bad_member");

        // observe before-values via public interface
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeMember = c.balanceOf(member);

        // attempt the mintSynth call and capture whether it reverted and the returned amount
        bool reverted = false;
        uint256 returnedMint = 0;
        try c.mintSynth(member, amount) returns (uint256 out) {
            returnedMint = out;
        } catch {
            reverted = true;
        }

        // read after-values
        uint256 afterTotal = c.totalSupply();
        uint256 afterMember = c.balanceOf(member);

        // Assert the general rule: if the call did not revert, both totalSupply and member balance
        // increased by exactly the returned minted amount. If it reverted, we make no claim.
        assert(reverted || (afterTotal == beforeTotal + returnedMint && afterMember == beforeMember + returnedMint));
    }

    receive() external payable { }
}
